import {
  type AfterContentInit,
  ChangeDetectionStrategy,
  Component,
  Directive,
  computed,
  contentChild,
  contentChildren,
  effect,
  input,
  viewChild,
} from '@angular/core';
import {
  MatError,
  MatFormField,
  MatFormFieldControl,
  MatHint,
  MatLabel,
  MatPrefix,
  MatSuffix,
  type MatFormFieldAppearance,
} from '@angular/material/form-field';
import type {
  AtomicSize,
  FormFieldAppearance,
  FormFieldFloatLabel,
  FormFieldMoleculeProps,
  FormFieldSubscriptSizing,
} from '@mono-magic/atomic-design-interfaces';
import type { SignalProps } from '../../core/signal-props';

interface ForcedErrorControl {
  setForcedError?(hasError: boolean): void;
}

/** Projects prefix content (icon or text) into `magic-form-field`. */
@Directive({
  selector: '[magicPrefix]',
})
export class MagicPrefixDirective {}

/** Projects suffix content (icon or text) into `magic-form-field`. */
@Directive({
  selector: '[magicSuffix]',
})
export class MagicSuffixDirective {}

/**
 * The only component in the library that renders `mat-form-field`.
 *
 * It wraps any control atom (`magic-text-input`, `magic-select`, ...) and adds
 * the floating label, hint, error message and `[magicPrefix]` / `[magicSuffix]`
 * slots.
 *
 * ```html
 * <magic-form-field label="Email" hint="We never share it">
 *   <magic-text-input type="email" />
 * </magic-form-field>
 * ```
 *
 * @see https://material.angular.dev/components/form-field/overview
 */
@Component({
  selector: 'magic-form-field',
  imports: [MatFormField, MatLabel, MatHint, MatError, MatPrefix, MatSuffix],
  templateUrl: './form-field.component.html',
  styleUrl: './form-field.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[attr.id]': 'null',
    '[class]': 'hostClasses()',
  },
})
export class MagicFormFieldComponent
  implements SignalProps<FormFieldMoleculeProps>, AfterContentInit
{
  /** Id of the field wrapper (removed from host). */
  readonly id = input<string>();
  /** Rendered as `data-testid` on the field. */
  readonly testId = input<string>();
  /** Accessible name; usually unnecessary when `label` is set. */
  readonly ariaLabel = input<string>();
  /** Floating label text. */
  readonly label = input<string>();
  /** Helper text shown under the control. */
  readonly hint = input<string>();
  /** Error message shown under the control; puts the projected control in an error state. */
  readonly errorText = input<string>();
  /** Material field appearance (`outlined` or `filled`). */
  readonly appearance = input<FormFieldAppearance>('outlined');
  /** Field size token (`xs`..`xl`). */
  readonly size = input<AtomicSize>('md');
  /** Floating label behaviour (`auto` or `always`). */
  readonly floatLabel = input<FormFieldFloatLabel>('auto');
  /** Whether subscript error/hint space is reserved (`fixed` or `dynamic`). */
  readonly subscriptSizing = input<FormFieldSubscriptSizing>('fixed');
  /** Hides the required asterisk next to the label. */
  readonly hideRequiredMarker = input(false);

  private readonly control = contentChild(MatFormFieldControl);
  private readonly prefixChildren = contentChildren(MagicPrefixDirective, {
    descendants: true,
  });
  private readonly suffixChildren = contentChildren(MagicSuffixDirective, {
    descendants: true,
  });
  private readonly matFormField = viewChild.required(MatFormField);

  protected readonly hasPrefix = computed(
    () => this.prefixChildren().length > 0,
  );
  protected readonly hasSuffix = computed(
    () => this.suffixChildren().length > 0,
  );

  protected readonly matAppearance = computed<MatFormFieldAppearance>(() =>
    this.appearance() === 'filled' ? 'fill' : 'outline',
  );

  protected readonly hostClasses = computed(() => `magic-size-${this.size()}`);

  constructor() {
    effect(() => {
      const control = this.control() as
        | (MatFormFieldControl<unknown> & ForcedErrorControl)
        | undefined;
      if (control) {
        this.matFormField()._control = control;
        control.setForcedError?.(Boolean(this.errorText()));
      }
    });
  }

  ngAfterContentInit(): void {
    // `mat-form-field` cannot see a control projected through <ng-content>,
    // so hand it over explicitly before MatFormField's own ngAfterContentInit runs.
    const control = this.control() as
      | (MatFormFieldControl<unknown> & ForcedErrorControl)
      | undefined;
    if (control) {
      this.matFormField()._control = control;
      control.setForcedError?.(Boolean(this.errorText()));
    }
  }
}

import {
  inject,
  type ModelSignal,
  type OutputRef,
  type Provider,
  type Type,
  type WritableSignal,
} from '@angular/core';
import {
  NG_VALUE_ACCESSOR,
  type ControlValueAccessor,
  type NgControl,
} from '@angular/forms';

/**
 * What a form-control atom must expose to be bridged to Reactive / template
 * driven forms. It deliberately mirrors the Signal Forms control contracts
 * (`FormValueControl` / `FormCheckboxControl`): a `value` or `checked`
 * `model()` plus a `touch` output. That means one component works with
 * `[formField]`, `formControlName`, `formControl` and `[(ngModel)]`.
 */
export interface MagicCvaTarget<T> {
  /** `FormValueControl` style model. Provide this OR `checked`. */
  readonly value?: ModelSignal<T>;
  /** `FormCheckboxControl` style model. Provide this OR `value`. */
  readonly checked?: ModelSignal<boolean>;
  /** Emit when the control loses focus. */
  readonly touch: OutputRef<void>;
  /** Written by `setDisabledState`; combine with your `disabled` input. */
  readonly formDisabled: WritableSignal<boolean>;
}

/**
 * Single, shared `ControlValueAccessor` implementation for every Magic form
 * atom. The atom itself stays free of `writeValue` / `registerOnChange`
 * boilerplate.
 */
export class MagicValueAccessor<T> implements ControlValueAccessor {
  private onChange: (value: T) => void = () => undefined;
  private onTouched: () => void = () => undefined;
  private writing = false;

  constructor(private readonly host: MagicCvaTarget<T>) {
    this.model.subscribe((next) => {
      if (!this.writing) {
        this.onChange(next as T);
      }
    });
    host.touch.subscribe(() => this.onTouched());
  }

  private get model(): ModelSignal<T> {
    const model = (this.host.value ?? this.host.checked) as
      | ModelSignal<T>
      | undefined;
    if (!model) {
      throw new Error(
        'MagicCvaTarget must expose either a `value` or a `checked` model().',
      );
    }
    return model;
  }

  writeValue(value: T | null): void {
    this.writing = true;
    try {
      this.model.set(value as T);
    } finally {
      this.writing = false;
    }
  }

  registerOnChange(fn: (value: T) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.host.formDisabled.set(isDisabled);
  }
}

/**
 * Registers the shared accessor on a component:
 *
 * ```ts
 * @Component({ providers: [provideMagicValueAccessor(() => MagicFooComponent)] })
 * ```
 */
export function provideMagicValueAccessor<T>(
  host: () => Type<MagicCvaTarget<T>>,
): Provider {
  return {
    provide: NG_VALUE_ACCESSOR,
    multi: true,
    useFactory: () => new MagicValueAccessor<T>(inject(host())),
  };
}

/**
 * Attaches the shared accessor directly onto an injected `NgControl`. Use this
 * for `MatFormFieldControl` components that inject `NgControl` themselves, to
 * avoid circular DI on `NG_VALUE_ACCESSOR`.
 */
export function bindMagicValueAccessor<T>(
  host: MagicCvaTarget<T>,
  ngControl: NgControl | null,
): MagicValueAccessor<T> | null {
  if (!ngControl) {
    return null;
  }
  const accessor = new MagicValueAccessor<T>(host);
  ngControl.valueAccessor = accessor;
  return accessor;
}

