import {
  ChangeDetectionStrategy,
  Component,
  input,
  output,
  viewChild,
  viewChildren,
} from '@angular/core';
import { MatIcon } from '@angular/material/icon';
import {
  MatMenu,
  MatMenuItem,
  MatMenuTrigger,
  type MenuCloseReason,
  type MenuPositionX,
  type MenuPositionY,
} from '@angular/material/menu';
import type { MenuItem } from '@mono-magic/atomic-design-interfaces';

/**
 * Recursive `mat-menu` panel renderer used internally by `MagicMenuComponent`
 * so each nesting level keeps its `mat-menu-item` children in its own light
 * DOM while supporting arbitrary submenu depth.
 *
 * @internal
 */
@Component({
  selector: 'magic-menu-submenu',
  imports: [MatMenu, MatMenuItem, MatMenuTrigger, MatIcon],
  templateUrl: './menu-submenu.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MagicMenuSubmenuComponent {
  /** Menu items rendered at this hierarchy level. */
  readonly items = input<readonly MenuItem[]>([]);
  /** Unique key matching this submenu back to its parent trigger item. */
  readonly ownerKey = input<string>('');
  /** Horizontal panel alignment relative to trigger. */
  readonly xPosition = input<MenuPositionX>('after');
  /** Vertical panel alignment relative to trigger. */
  readonly yPosition = input<MenuPositionY>('below');
  /** Whether the menu overlaps its trigger. */
  readonly overlapTrigger = input(false);
  /** Whether a backdrop appears behind the open menu. */
  readonly hasBackdrop = input(true);
  /** CSS class applied to the menu backdrop. */
  readonly backdropClass = input<string>('');
  /** CSS class applied to the menu overlay panel. */
  readonly panelClass = input<string>('');
  /** Accessible label for the menu panel (`aria-label`). */
  readonly ariaLabel = input<string>();
  /** Accessible `aria-labelledby` reference for the menu panel. */
  readonly ariaLabelledby = input<string>();
  /** Accessible `aria-describedby` reference for the menu panel. */
  readonly ariaDescribedby = input<string>();

  /** Underlying `MatMenu` instance referenced by parent `[matMenuTriggerFor]`. */
  readonly matMenu = viewChild.required(MatMenu);
  private readonly nestedPanels = viewChildren(MagicMenuSubmenuComponent);

  /** Emits when a leaf menu item is activated. */
  readonly itemSelected = output<MenuItem>();
  /** Emits when this menu panel closes. */
  readonly closed = output<MenuCloseReason>();

  protected itemKey(item: MenuItem, index: number): string {
    return `${index}:${item.id ?? item.label}`;
  }

  protected submenuFor(item: MenuItem, index: number): MatMenu | null {
    const key = this.itemKey(item, index);
    return (
      this.nestedPanels()
        .find((panel) => panel.ownerKey() === key)
        ?.matMenu() ?? null
    );
  }

  protected selectItem(item: MenuItem): void {
    if (!item.disabled) {
      this.itemSelected.emit(item);
    }
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
} from '@angular/core';
import { MatProgressBar } from '@angular/material/progress-bar';
import {
  MatProgressSpinner,
  type ProgressSpinnerMode,
} from '@angular/material/progress-spinner';
import type {
  AtomicSize,
  ColorIntent,
  ProgressIndicatorAtomProps,
  ProgressIndicatorMode,
  ProgressIndicatorType,
} from '@mono-magic/atomic-design-interfaces';
import type { SignalProps } from '../../core/signal-props';

const SIZE_DIAMETERS: Record<AtomicSize, number> = {
  xs: 20,
  sm: 28,
  md: 40,
  lg: 56,
  xl: 72,
};

const SIZE_STROKES: Record<AtomicSize, number> = {
  xs: 2,
  sm: 3,
  md: 4,
  lg: 5,
  xl: 6,
};

/**
 * Wraps Angular Material's `mat-progress-bar` and `mat-progress-spinner` behind
 * one signal-driven atomic API. Preserves exact numeric `0` values.
 *
 * @see https://material.angular.dev/components/progress-bar/overview
 * @see https://material.angular.dev/components/progress-spinner/overview
 */
@Component({
  selector: 'magic-progress-indicator',
  imports: [MatProgressBar, MatProgressSpinner],
  templateUrl: './progress-indicator.component.html',
  styleUrl: './progress-indicator.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[attr.id]': 'null',
    '[class]': 'hostClasses()',
  },
})
export class MagicProgressIndicatorComponent
  implements SignalProps<ProgressIndicatorAtomProps>
{
  /** Id applied to the inner bar or spinner (removed from host). */
  readonly id = input<string>();
  /** Rendered as `data-testid`. */
  readonly testId = input<string>();
  /** Accessible name for assistive tech. */
  readonly ariaLabel = input<string>();
  /** Visual type (`'bar'` or `'spinner'`). */
  readonly type = input<ProgressIndicatorType>('bar');
  /** Animation/progress mode (`'determinate'`, `'indeterminate'`, `'buffer'`, `'query'`). */
  readonly mode = input<ProgressIndicatorMode>('indeterminate');
  /** Progress percentage (`0`..`100`). */
  readonly value = input<number>(0);
  /** Buffer percentage (`0`..`100`) when `type='bar'` and `mode='buffer'`. */
  readonly bufferValue = input<number>(0);
  /** Explicit spinner diameter in pixels (defaults from `size` when unset). */
  readonly diameter = input<number | undefined>(undefined);
  /** Explicit spinner stroke width in pixels (defaults from `size` when unset). */
  readonly strokeWidth = input<number | undefined>(undefined);
  /** Disables the indicator (part of `BaseAtomProps`). */
  readonly disabled = input(false);
  /** Semantic color role. */
  readonly color = input<ColorIntent>('primary');
  /** Size token (`xs`..`xl`). */
  readonly size = input<AtomicSize>('md');

  protected readonly spinnerMode = computed<ProgressSpinnerMode>(() =>
    this.mode() === 'determinate' ? 'determinate' : 'indeterminate',
  );

  protected readonly resolvedDiameter = computed(
    () => this.diameter() ?? SIZE_DIAMETERS[this.size()],
  );

  protected readonly resolvedStrokeWidth = computed(
    () => this.strokeWidth() ?? SIZE_STROKES[this.size()],
  );

  protected readonly hostClasses = computed(() =>
    [
      `magic-size-${this.size()}`,
      `magic-color-${this.color()}`,
      this.type() === 'spinner' ? 'magic-progress-indicator--spinner' : '',
    ]
      .filter(Boolean)
      .join(' '),
  );
}

